import numpy as np


class DataProcessor:
    def __init__(self, config):
        self.config = config

    def process(self, data):
        arr = np.asarray(data)

        if self.config.get('filter'):
            mask = np.asarray(self.config['filter'](arr), dtype=bool)
            arr = arr[mask]

        if self.config.get('transform'):
            arr = np.asarray(self.config['transform'](arr))

        return arr

